import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"近期开发复盘：疑难杂症、架构选择与工程验证","description":"21 篇近期技术文章，重点记录踩坑现场、架构选择、问题分析、修复动作与实机验证","frontmatter":{"title":"近期开发复盘：疑难杂症、架构选择与工程验证","description":"21 篇近期技术文章，重点记录踩坑现场、架构选择、问题分析、修复动作与实机验证","tags":["RK3588","Rockit","PX4","Linux","工程实践"],"date":"2026/07/20"},"headers":[],"relativePath":"notes/2026-technical-review.md","filePath":"notes/2026-technical-review.md","lastUpdated":1784519165000}'),i={name:"notes/2026-technical-review.md"};function n(o,t,l,c,h,s){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="近期开发复盘-从疑难问题到架构与验证闭环" tabindex="-1">近期开发复盘：从疑难问题到架构与验证闭环 <a class="header-anchor" href="#近期开发复盘-从疑难问题到架构与验证闭环" aria-label="Permalink to &quot;近期开发复盘：从疑难问题到架构与验证闭环&quot;">​</a></h1><p>近期整理了 21 篇技术文章，重点不是展示“最后怎么配置”，而是保留完整的问题解决过程：<strong>现场出现什么症状、最初判断哪里错了、证据怎样收敛、为什么做出这个架构选择、修复后又如何证明。</strong></p><p>内容从多媒体框架、DMA-BUF、NPU、VINS、时间同步延伸到 MAVLink 与混合架构 CI。看似分散，实际都在回答同一个问题：怎样从一个模糊故障出发，建立可验证的证据链，并把一次修复沉淀成可复用的工程方法。</p><h2 id="failure-notes" tabindex="-1">问题复盘优先阅读 <a class="header-anchor" href="#failure-notes" aria-label="Permalink to &quot;问题复盘优先阅读 {#failure-notes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现场症状</th><th>容易做出的错误判断</th><th>最终要追的根因</th><th>文章</th></tr></thead><tbody><tr><td>FP16 模型能跑，但不知道输入应该是什么类型</td><td>根据模型名称直接硬编码 dtype</td><td>模型精度、Runtime 输入与 NPU 计算精度混淆</td><td><a href="/linux/rknn-npu-input-pipeline">NPU 输入踩坑复盘</a></td></tr><tr><td>换成 DMA-BUF 后 CPU 仍然很高</td><td>以为换接口就等于移除复制</td><td>ROS、颜色转换、float32 物化和 Runtime 转换仍在</td><td><a href="/linux/rknn-npu-input-pipeline">NPU 输入踩坑复盘</a></td></tr><tr><td><code>has_sync=True</code>，相机与 IMU 仍有固定偏差</td><td>把链路在线当成端到端同步</td><td>message stamp 没有统一到同一 time domain</td><td><a href="/uav/timesync-qa-engineering">时间同步 QA 工程化</a></td></tr><tr><td><code>NTPSynchronized=yes</code>，却找不到 NTP 校时流量</td><td>只相信状态字段</td><td>实际校时源可能是 PTP → PHC → phc2sys</td><td><a href="/linux/rtc-ptp-time-source">RTC、PTP 与真实校时源</a></td></tr><tr><td>CI 换源后 amd64 正常、arm64 仍失败</td><td>继续更换同一套镜像地址</td><td>两种架构对应不同 archive 拓扑</td><td><a href="/linux/mixed-arch-ci-apt">混合架构 CI 的 APT 源</a></td></tr><tr><td>DMA-BUF fd 已发送，下游仍偶发读到污染帧</td><td>认为 fd 传递完成就能立即复用</td><td>buffer ownership、ACK 与复用时序不完整</td><td><a href="/linux/dmabuf-ownership-contract">跨进程 DMA-BUF 所有权合同</a></td></tr><tr><td><code>CmaFree=0</code>，看起来 1 GiB CMA 已耗尽</td><td>直接扩容或杀进程</td><td>kernel 开启 <code>CMA_INACTIVE</code>，统计字段不能直接代表 headroom</td><td><a href="/linux/rk3588-cma-dmabuf-memory-debug">RK3588 CMA 排障复盘</a></td></tr><tr><td>服务显示 active，下游仍无限重连</td><td>继续增加重试和启动延迟</td><td>配置组合无法生产 consumer 所需的数据</td><td><a href="/linux/service-active-not-ready">Service Active 但未 Ready</a></td></tr><tr><td>CI job 被触发，脚本却因 fingerprint 未变退出</td><td>认为只是一次无害空跑</td><td>trigger 集与 artifact fingerprint 输入集合不一致</td><td><a href="/linux/ci-trigger-fingerprint-contract">CI Trigger 与 Fingerprint</a></td></tr><tr><td>模型能解密，但无法证明内容是批准版本</td><td>把“解密成功”当完整性验证</td><td>缺少内层 payload hash 与 lock file 合同</td><td><a href="/linux/model-asset-ci-integrity-gate">模型资产完整性门禁</a></td></tr><tr><td>源码已修复，板端行为仍像旧版本</td><td>继续修改算法代码</td><td>package、资产、进程身份与 source commit 没有闭环</td><td><a href="/linux/release-package-traceability">发布包与源码追踪</a></td></tr></tbody></table><h2 id="文章地图" tabindex="-1">文章地图 <a class="header-anchor" href="#文章地图" aria-label="Permalink to &quot;文章地图&quot;">​</a></h2><h3 id="vision-pipeline" tabindex="-1">RK3588 高性能视觉 <a class="header-anchor" href="#vision-pipeline" aria-label="Permalink to &quot;RK3588 高性能视觉 {#vision-pipeline}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th></tr></thead><tbody><tr><td><a href="/linux/rk3588-camera-pipeline">RK3588 高性能相机流水线</a></td><td>如何建立 V4L2 → RGA → OpenCL → 算法/MPP 的单一生产主链</td></tr><tr><td><a href="/linux/camera-single-owner-no-runtime-fallback">单一 Owner 与显式失败</a></td><td>为什么生产链拒绝多 owner 和静默 CPU fallback，并如何保留可审计回滚</td></tr><tr><td><a href="/linux/rockit-vs-mpp">Rockit 与 MPP 对比分析</a></td><td>完整多媒体管线与单独编解码该怎样选型</td></tr><tr><td><a href="/linux/dmabuf-heaps-cma">DMA-BUF Heaps 与 CMA</a></td><td>分配接口、共享句柄和连续内存后端分别处在哪一层</td></tr><tr><td><a href="/linux/rk3588-cma-dmabuf-memory-debug">RK3588 CMA 排障复盘</a></td><td><code>CmaFree=0</code> 为什么不是耗尽结论，以及 384/512 MiB 怎样做生产选择</td></tr><tr><td><a href="/linux/dmabuf-ownership-contract">跨进程 DMA-BUF 所有权合同</a></td><td><code>SCM_RIGHTS</code> 发送 fd 后，buffer 何时才能安全复用</td></tr><tr><td><a href="/linux/rk3588-performance-ab">RK3588 板端性能 A/B</a></td><td>如何证明资源下降不是版本混用或功能缺失造成的</td></tr><tr><td><a href="/linux/rknn-npu-input-pipeline">NPU 输入踩坑复盘</a></td><td>FP16、DMA-BUF、CPU 热点、重复物化与 layout 漂移是怎样定位和修复的</td></tr><tr><td><a href="/linux/rknn-input-dtype">RKNN 输入 dtype</a></td><td>模型精度、Runtime 输入类型和 NPU 计算精度怎样区分</td></tr></tbody></table><h3 id="time-systems" tabindex="-1">时间系统与 VIO <a class="header-anchor" href="#time-systems" aria-label="Permalink to &quot;时间系统与 VIO {#time-systems}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th></tr></thead><tbody><tr><td><a href="/uav/timesync-time-sync-node">RK3588 与 PX4 高精度时间同步</a></td><td>怎样用 PPS 共同事件估计跨时钟域 offset</td></tr><tr><td><a href="/uav/timesync-qa-engineering">时间同步 QA 工程化</a></td><td>为什么 <code>has_sync=True</code> 不是端到端同步结论</td></tr><tr><td><a href="/uav/camera-imu-timestamp-semantics">相机与 IMU 时间戳语义</a></td><td>固定 4ms/9ms 偏差为什么更像 PTS、曝光或 <code>td</code> 问题</td></tr><tr><td><a href="/uav/vins-direct-grayscale-dmabuf">VINS 直连灰度 DMA-BUF</a></td><td>如何移除 ROS 图像复制，同时保留 IMU 与 odometry 接口</td></tr></tbody></table><h3 id="protocol-delivery" tabindex="-1">协议与工程交付 <a class="header-anchor" href="#protocol-delivery" aria-label="Permalink to &quot;协议与工程交付 {#protocol-delivery}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th></tr></thead><tbody><tr><td><a href="/uav/mavlink-wire-type-semantics">MAVLink wire type 与业务语义</a></td><td><code>uint8_t</code> byte 如何承载 signed dBm，extension 又如何守住长度边界</td></tr><tr><td><a href="/linux/mixed-arch-ci-apt">混合架构 CI 的 APT 源</a></td><td>amd64 与 arm64 为什么必须对应不同 archive 拓扑</td></tr><tr><td><a href="/linux/rtc-ptp-time-source">RTC、PTP 与真实校时源</a></td><td><code>NTPSynchronized=yes</code> 为什么不能证明 NTP 正在校时</td></tr><tr><td><a href="/linux/rk3588-gpio-calculation">RK3588 GPIO 编号计算</a></td><td>怎样从 Bank、Group、Pin 推导 line offset 并在板端确认</td></tr></tbody></table><h3 id="delivery-gates" tabindex="-1">疑难排障与交付门禁 <a class="header-anchor" href="#delivery-gates" aria-label="Permalink to &quot;疑难排障与交付门禁 {#delivery-gates}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th></tr></thead><tbody><tr><td><a href="/linux/service-active-not-ready">Service Active 但未 Ready</a></td><td>为什么进程存活不能证明数据链健康，以及怎样建立 readiness 验收</td></tr><tr><td><a href="/linux/ci-trigger-fingerprint-contract">CI Trigger 与 Fingerprint</a></td><td>如何让触发路径、source hash 与真实 artifact contract 保持一致</td></tr><tr><td><a href="/linux/model-asset-ci-integrity-gate">模型资产完整性门禁</a></td><td>怎样同时证明模型已加密、可解密且内层内容匹配批准版本</td></tr><tr><td><a href="/linux/release-package-traceability">发布包与源码追踪</a></td><td>怎样证明板端真实运行的是目标源码、配置、模型和 package</td></tr></tbody></table><h2 id="架构选择索引" tabindex="-1">架构选择索引 <a class="header-anchor" href="#架构选择索引" aria-label="Permalink to &quot;架构选择索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>放弃的方案</th><th>选择理由</th><th>文章</th></tr></thead><tbody><tr><td>相机 runtime 保持单一 owner</td><td>多个采集节点各自拥有设备与 buffer pool</td><td>避免设备争抢、时间语义分叉和恢复路径歧义</td><td><a href="/linux/camera-single-owner-no-runtime-fallback">单一 Owner 与显式失败</a></td></tr><tr><td>生产链能力不足时显式失败</td><td>OpenCL 失败后静默切换 CPU</td><td>防止服务看似健康但性能、延迟和热状态已经改变</td><td><a href="/linux/camera-single-owner-no-runtime-fallback">单一 Owner 与显式失败</a></td></tr><tr><td>Atlas 作为单一物理存储</td><td>Atlas 与四对独立图像同时物化</td><td>ROI view 能表达逻辑切片，不增加复制与 CMA 压力</td><td><a href="/linux/rknn-npu-input-pipeline">NPU 输入踩坑复盘</a></td></tr><tr><td>Layout 由 producer 进入 typed contract</td><td>Consumer 通过宽高常量自行推断</td><td>让几何变化在边界处失败，而不是静默输出错误结果</td><td><a href="/linux/rknn-npu-input-pipeline">NPU 输入踩坑复盘</a></td></tr><tr><td>实时 consumer 使用 Latest，关键阶段使用有界队列</td><td>所有支路同步阻塞或无限积压</td><td>过载策略可预测，慢 consumer 不拖死生产者</td><td><a href="/linux/camera-single-owner-no-runtime-fallback">单一 Owner 与显式失败</a></td></tr><tr><td>模型策略使用独立 CI gate</td><td>把检查埋进完整工程 build</td><td>失败更快、更清晰，资产规则长期可审计</td><td><a href="/linux/model-asset-ci-integrity-gate">模型资产完整性门禁</a></td></tr></tbody></table><h2 id="_1-rockit-与-mpp-先分清层次-再谈选型" tabindex="-1">1. Rockit 与 MPP：先分清层次，再谈选型 <a class="header-anchor" href="#_1-rockit-与-mpp-先分清层次-再谈选型" aria-label="Permalink to &quot;1. Rockit 与 MPP：先分清层次，再谈选型&quot;">​</a></h2><p><a href="/linux/rockit-vs-mpp">《Rockit 与 MPP 对比分析》</a>首先澄清了一个常见误区：Rockit 和 MPP 不是简单的竞品关系。</p><ul><li><strong>MPP</strong> 位于编解码层，适合文件转码、单独编码或需要轻量集成的场景。</li><li><strong>Rockit</strong> 位于完整多媒体管线层，覆盖 VI、VPSS、VENC、VO 等模块，并通过 Bind 和统一内存块组织数据流。</li><li>Rockit 的编解码能力仍建立在 MPP 之上，真正的差异是它是否帮应用管理采集、处理、编码、显示和跨模块内存。</li></ul><p>这篇文章最重要的结论不是“哪个更强”，而是：<strong>选型取决于你要解决的是一个编解码问题，还是一条完整的视频管线。</strong></p><p>对于 RK3588 上的摄像头、AI 前处理和编码场景，这个边界会直接影响内存搬运、DMA-BUF 共享、模块所有权与后续维护成本。</p><h2 id="_2-gpio-编号-把命名规则变成公式" tabindex="-1">2. GPIO 编号：把命名规则变成公式 <a class="header-anchor" href="#_2-gpio-编号-把命名规则变成公式" aria-label="Permalink to &quot;2. GPIO 编号：把命名规则变成公式&quot;">​</a></h2><p><a href="/linux/rk3588-gpio-calculation">《RK3588 GPIO 编号计算指南》</a>把 <code>GPIO3_D4</code> 这样的硬件命名拆成 Bank、Group、Pin 三部分：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bank 内偏移 = Group 偏移 + Pin</span></span>
<span class="line"><span>全局编号 = Bank × 32 + Bank 内偏移</span></span></code></pre></div><p>公式本身并不复杂，真正容易出错的是接口语义：libgpiod 通常接收的是某个 gpiochip 内部的 line offset，而不是全局编号。</p><p>因此，计算只是第一步，实际使用时还要通过 <code>gpiodetect</code> 和 <code>gpioinfo</code> 确认 gpiochip 的注册顺序与 line 映射。这里体现的是嵌入式开发里很重要的习惯：<strong>公式负责建立模型，系统接口负责确认模型与当前设备一致。</strong></p><h2 id="_3-px4-时间同步-用同一个物理事件连接两个时钟域" tabindex="-1">3. PX4 时间同步：用同一个物理事件连接两个时钟域 <a class="header-anchor" href="#_3-px4-时间同步-用同一个物理事件连接两个时钟域" aria-label="Permalink to &quot;3. PX4 时间同步：用同一个物理事件连接两个时钟域&quot;">​</a></h2><p><a href="/uav/timesync-time-sync-node">《RK3588 与 PX4 飞控高精度时间同步》</a>处理的是一个更隐蔽的问题：PX4 飞控与 RK3588 机载计算机拥有不同的时钟基准，传感器时间戳不能直接混用。</p><p>方案使用同一个 PPS 上升沿作为共同事件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RK3588 时间 = PX4 时间 + offset</span></span>
<span class="line"><span>offset = RK3588 捕获 PPS 的时间 - PX4 记录 PPS 的时间</span></span></code></pre></div><p>因为两端比较的是同一个硬件事件，串口传输延迟不会直接进入 offset；串口只负责把 PX4 已记录的事件时间带到 RK3588。随后再用 EMA 对 GPIO 中断延迟和晶振漂移带来的抖动做平滑。</p><p>这篇文章的核心不是某个滤波参数，而是同步设计的原则：<strong>先找到跨时钟域共同可见的事件，再围绕这个事件估计和维护偏移。</strong></p><h2 id="_4-这一批文章的共同方法" tabindex="-1">4. 这一批文章的共同方法 <a class="header-anchor" href="#_4-这一批文章的共同方法" aria-label="Permalink to &quot;4. 这一批文章的共同方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>Rockit / MPP</th><th>RK3588 GPIO</th><th>PX4 时间同步</th></tr></thead><tbody><tr><td>划清边界</td><td>编解码层与多媒体管线层</td><td>全局编号与 chip 内偏移</td><td>PX4 boot time 与 Linux monotonic time</td></tr><tr><td>建立模型</td><td>模块、Bind 与内存关系</td><td>Bank × 32 + Group + Pin</td><td>本地时间 = 飞控时间 + offset</td></tr><tr><td>真实验证</td><td>数据是否沿预期模块流转</td><td><code>gpiodetect</code> / <code>gpioinfo</code></td><td>PPS 捕获、时间戳与 offset 稳定性</td></tr></tbody></table><p>这套方法可以复用到更多板端问题：不要从零散 API 开始堆代码，而是先明确谁拥有数据、边界在哪里、哪些量可以被观测。模型成立后，再用真实设备上的接口、时间戳或数据流完成闭环。</p><h2 id="_5-工程环境延伸阅读" tabindex="-1">5. 工程环境延伸阅读 <a class="header-anchor" href="#_5-工程环境延伸阅读" aria-label="Permalink to &quot;5. 工程环境延伸阅读&quot;">​</a></h2><p>如果要补齐工程环境，可以继续阅读：</p><ul><li><a href="/linux/ubuntu_cmake3.25">Ubuntu 22.04 编译安装 CMake 3.25</a>：解决 PX4、RK3588 SDK 等项目的工具链版本要求。</li><li><a href="/linux/docker_not_sudo">Docker 免 sudo 使用</a>：整理开发机上的容器权限配置。</li><li><a href="/linux/harbor">搭建 Harbor 私有镜像仓库</a>：把本地构建进一步接入可控的镜像交付链路。</li></ul><p>这 21 篇内容已经形成一套相互连接的阅读路径：从故障现场和错误假设开始，进入平台分层、相机/VINS 主链与架构选择，再落到时间语义、协议边界、CI 门禁和板端验证。后续新增内容也会继续优先记录“问题怎样解决”，而不是变成孤立的配置笔记。</p>`,39)])])}const f=e(i,[["render",n]]);export{u as __pageData,f as default};
